-- =====================================================================================================
-- PostgreSQL-only additions, applied after schema.sql (order: schema.sql -> schema_postgres.sql -> mart.sql).
-- DuckDB has no partial or GIN indexes, so these rules are checked there by src/quality.py instead.
-- =====================================================================================================

-- surrogate key generated by the database when rows are inserted one by one (the batch load supplies it)
ALTER TABLE participation ALTER COLUMN participation_id ADD GENERATED BY DEFAULT AS IDENTITY;

-- business rule "a project has at most one coordinator", enforced by a partial unique index
-- (the "at least one" part is a deferred check: quality check Q01)
CREATE UNIQUE INDEX ux_one_coordinator_per_project ON participation (project_id) WHERE role_code = 'coordinator';

-- full-text search on project objectives (e.g. "which projects work on hydrogen storage?")
CREATE INDEX ix_project_objective_fts ON project USING gin (to_tsvector('english', coalesce(objective, '')));

-- the many-to-many tables are read from both sides
CREATE INDEX ix_ppp_part ON project_programme_part (part_code);
